from pathlib import Path
from playwright.sync_api import sync_playwright
from batch5_browser_utils import bundled_creator_explorer,bundled_creator_scene
import json
root=Path(__file__).resolve().parents[1];icons=[];scenes=[]
with sync_playwright() as p:
    b=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium');page=b.new_page(viewport={'width':1720,'height':1100});page.set_content(bundled_creator_explorer(root),wait_until='load')
    icons=page.evaluate('''()=>[...document.querySelectorAll('.nex-icon')].map(icon=>{const tl=icon.__tl,def=NexCreatorIcons.getDef(icon.dataset.iconId);function snap(){return JSON.stringify([icon,...icon.querySelectorAll('*')].slice(0,100).map(n=>{const c=getComputedStyle(n);return [n.tagName,n.className,c.transform,c.opacity,c.strokeDashoffset,n.textContent]}))}const samples=[];for(let i=0;i<=10;i++){const t=tl.duration()*i/10;tl.seek(t);samples.push({time:t,state:snap()})}let changes=0;for(let i=1;i<samples.length;i++)if(samples[i].state!==samples[i-1].state)changes++;const internal=tl.entries?.[1]?.timeline||tl;const parts=[...icon.querySelectorAll('.icon-symbol-layer *')];const partStates=parts.map(part=>{const s=[.1,.35,.65,.95].map(v=>{internal.seek(internal.duration()*v);const c=getComputedStyle(part);return JSON.stringify([c.transform,c.opacity,c.strokeDashoffset,part.textContent])});return {part:part.getAttribute('class')||part.tagName,distinct:new Set(s).size}});return {id:def.id,slug:def.slug,duration:tl.duration(),bespoke:def.bespokeInternalMotion,changes,semanticChangedParts:partStates.filter(x=>x.distinct>1).length,partCount:partStates.length}})''');page.close()
    for name,vp in [('creator-workflow',{'width':1920,'height':1080}),('media-production',{'width':1080,'height':1080}),('publishing',{'width':1080,'height':1920})]:
        page=b.new_page(viewport=vp);page.set_content(bundled_creator_scene(root,name),wait_until='load')
        result=page.evaluate('''name=>{const tl=window.__timelines[name],times=[],states=[];for(let t=0;t<=10.2+.001;t+=.2){tl.seek(t);const state=JSON.stringify([...document.querySelectorAll('.creator-node,.creator-scene-copy>*,.nex-icon,.nex-icon *')].map(n=>{const c=getComputedStyle(n);return [n.className,c.transform,c.opacity,c.strokeDashoffset,n.textContent]}));times.push(Number(t.toFixed(2)));states.push(state)}let changes=[],dead=[],start=0;for(let i=1;i<states.length;i++){if(states[i]!==states[i-1]){changes.push(times[i]);if(times[i]-start>1.01)dead.push({from:start,to:times[i],duration:times[i]-start});start=times[i]}}if(10.2-start>1.01)dead.push({from:start,to:10.2,duration:10.2-start});return {name,duration:tl.duration(),sampleCount:times.length,changeCount:changes.length,deadZones:dead,firstChange:changes[0],lastChange:changes.at(-1)}}''',name);scenes.append(result);page.close()
    b.close()
icon_fail=[x for x in icons if x['changes']<4 or (x['bespoke'] and x['semanticChangedParts']<1)];scene_fail=[x for x in scenes if x['deadZones'] or x['changeCount']<20 or abs(x['duration']-10.2)>.01]
status=len(icons)==48 and sum(x['bespoke'] for x in icons)==18 and not icon_fail and not scene_fail
report={'status':'PASS' if status else 'FAIL','iconCount':len(icons),'bespokeCount':sum(x['bespoke'] for x in icons),'totalSampledIconChanges':sum(x['changes'] for x in icons),'semanticMotionFailures':icon_fail,'sceneCount':len(scenes),'sceneFailures':scene_fail,'scenes':scenes,'icons':icons}
(root/'reports/batch5-animation-map.json').write_text(json.dumps(report,indent=2));print(json.dumps({k:v for k,v in report.items() if k not in ['icons']},indent=2));raise SystemExit(0 if status else 1)
